    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Load data (en=1)", test_num);
            reset_dut();
            d = 10'h3FF;
            en = 1;
            @(posedge clk);
            #1;
            #1;

            check_outputs(10'h3FF);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Hold data (en=0)", test_num);
            reset_dut();

            d = 10'h155;
            en = 1;
            @(posedge clk);
            #1;

            en = 0;
            d = 10'h2AA;
            @(posedge clk);
            #1;

            #1;


            check_outputs(10'h155);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Reset priority over enable", test_num);
            reset_dut();

            d = 10'h0F0;
            en = 1;
            rst = 1;
            @(posedge clk);
            #1;

            #1;


            check_outputs(10'h000);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Sequence of operations", test_num);
            reset_dut();

            d = 10'h123; en = 1; @(posedge clk);

            d = 10'h234; en = 1; @(posedge clk);

            d = 10'h001; en = 0; @(posedge clk);

            d = 10'h05A; en = 1; @(posedge clk);
            #1;
            #1;

            check_outputs(10'h05A);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
