module elevator_controller (
  input up,
  input down,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg [1:0] floor);parameter G=0, F1=1, F2=2, F3=3;

    always_comb begin
        case (state)
            G: next_state = up ? F1 : G;
            F1: next_state = up ? F2 : (down ? G : F1);
            F2: next_state = up ? F3 : (down ? F1 : F2);
            F3: next_state = down ? F2 : F3;
        endcase
    end

    always_comb begin
        case (state)
            G: floor = 2'b00;
            F1: floor = 2'b01;
            F2: floor = 2'b10;
            F3: floor = 2'b11;
        endcase
    end

endmodule

