description:
Design a 4-to-1 multiplexer that selects one of four input lines based on a 2-bit selection signal. The module first uses two 2-to-1 multiplexers to combine pairs of inputs, and then a 2-bit decoder to generate enable signals for selecting the appropriate output from these multiplexed results. The final output is determined by the combination of the decoder's enable signals and the outputs of the multiplexers, ensuring that only one of the input lines is passed through to the output based on the selection criteria.
module top_module(
    input wire [3:0] in,
    input wire [1:0] sel,
    output reg out
);

code:
module top_module(
    input wire [3:0] in,
    input wire [1:0] sel,
    output reg out
);wire [3:0] mux_out;
    wire [3:0] dec_out;

    // 2-to-1 multiplexer
    assign mux_out[0] = (sel[0] == 0) ? in[0] : in[1];
    assign mux_out[1] = (sel[0] == 0) ? in[2] : in[3];

    // 2-bit decoder
    assign dec_out[0] = (sel[1] == 0) ? 1'b1 : 1'b0;
    assign dec_out[1] = (sel[1] == 1) ? 1'b1 : 1'b0;
    assign dec_out[2] = (sel[1] == 2) ? 1'b1 : 1'b0;
    assign dec_out[3] = (sel[1] == 3) ? 1'b1 : 1'b0;

    // Output
    assign out = (dec_out & mux_out);

endmodule

