module top_module(
  clk_fast,
  clk_slow,
  signal_i,
  signal_o
);//////////// INPUTS & OUTPUTS ////////////
  input clk_fast;
  input clk_slow;
  input signal_i;
  output signal_o;

  //////////// PARAMETERS ////////////
  parameter COUNT = 15; // with clk of 1.5kHz corresponds to 10ms width

  parameter s_idle = 0;
  parameter s_out = 1;

  //////////// SIGNALS & REGS ////////////
  reg[15:0] cnt = 0;
  reg state = 0;

  //////////// LOGIC ////////////

  // runs at fast clock to catch input signal
  always @(posedge clk_fast) begin
    case(state)
      s_idle:
      begin
        state <= (signal_i) ? s_out : s_idle;
      end
      s_out:
      begin
        state <= (cnt >= COUNT) ? s_idle : s_out;
      end
    endcase
  end

  // runs at slow clock to increment slowly
  always @(posedge clk_slow) begin
    if (state == s_out) cnt <= cnt + 8'b1;
    else if (state == s_idle) cnt  <= 8'b0;
  end

  //////////// OUTPUT ASSIGNS ////////////
  assign signal_o = (state == s_out);

endmodule

