module top_module(
    input wrclk,
    input write,
    input [15:0] din,
    input [1:0] min,
    output full,

    input rdclk,
    input read,
    output reg [15:0] dout,  // Changed from wire to reg
    output reg [1:0] mout,    // Changed from wire to reg
    output empty
);reg [15:0] fifo [15:0];
reg [4:0] wr_ptr;
reg [4:0] rd_ptr;
reg [4:0] depth;
reg [1:0] mask;
wire [4:0] next_wr_ptr;
wire [4:0] next_rd_ptr;
wire [4:0] next_depth;
wire [1:0] next_mask;
wire wr_en;
wire rd_en;
wire fifo_full;
wire fifo_empty;

assign next_wr_ptr = wr_ptr + 1;
assign next_rd_ptr = rd_ptr + 1;
assign next_depth = depth + wr_en - rd_en;
assign next_mask = min;

assign wr_en = write & !fifo_full;
assign rd_en = read & !fifo_empty;
assign fifo_full = (depth == 16);
assign fifo_empty = (depth == 0);

always @(posedge wrclk) begin
    if(wr_en) begin
        fifo[wr_ptr] <= din;
        wr_ptr <= next_wr_ptr;
        depth <= next_depth;
        mask <= next_mask;
    end
end

always @(posedge rdclk) begin
    if(rd_en) begin
        dout <= fifo[rd_ptr];  // dout can now be assigned because it is a reg
        mout <= mask;          // mout can now be assigned because it is a reg
        rd_ptr <= next_rd_ptr;
        depth <= next_depth;
        mask <= next_mask;
    end
end

assign full = fifo_full;
assign empty = fifo_empty;

endmodule

